import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Decision, Effort, Pending, Tier } from '../types'

const pending = atom({ plugin: 'triage-gate', key: 'pending' } as const, null)
const asking = atom({ plugin: 'triage-gate', key: 'asking' } as const, null)
const override = atom({ plugin: 'triage-gate', key: 'override' } as const, null)
const isOn = atom({ plugin: 'triage-gate', key: 'isOn' } as const, true)
const isModal = atom({ plugin: 'triage-gate', key: 'isModal' } as const, true)
const shownModel = atom({ plugin: 'triage-gate', key: 'shownModel' } as const, '')
const shownEffort = atom({ plugin: 'triage-gate', key: 'shownEffort' } as const, '')
const decision = atom({ plugin: 'triage-gate', key: 'decision' } as const, { verdict: 'Nenhuma mensagem avaliada ainda' })
const isBandOpen = atom({ plugin: 'triage-gate', key: 'isBandOpen' } as const, true)

export const TIERS: readonly Tier[] = ['haiku', 'sonnet', 'opus']

export type Verdict = { family: Tier; effort: Effort; reason: string }

export type Choice = 'switch' | 'send' | 'cancel'

const EFFORT_PT: Record<Effort, string> = { low: 'baixo', medium: 'médio', high: 'alto' }

const CONTINUATION = /^(sim|n[ãa]o|ok|pode|continu\w*|segu\w*|faz|vai|isso|beleza|certo|quero|bora|valeu|obrigad\w+|manda|tenta|vamos|testa|teste)\b/i

export function isSkippable(text: string): boolean {
  const trimmed = text.trim()
  return trimmed.length < 12 || trimmed.startsWith('/') || (trimmed.length < 60 && CONTINUATION.test(trimmed))
}

export function familyOf(modelId: string): Tier | null {
  const family = /(haiku|sonnet|opus)/i.exec(modelId)?.[1]?.toLowerCase()
  return family === undefined ? null : (family as Tier)
}

export function capitalize(text: string): string {
  return text.charAt(0).toUpperCase() + text.slice(1)
}

const MODEL = /^(?:claude[-\s])?(haiku|sonnet|opus|fable)(?:[-\s]?(\d{1,2})(?:[-.\s](\d{1,2}))?)?/i

export function prettyModel(raw: string): string {
  const match = MODEL.exec(raw.trim())
  if (match === null) return raw.trim()
  const version = match[2] === undefined ? '' : match[3] === undefined ? match[2] : `${match[2]}.${match[3]}`
  const family = capitalize(match[1]!.toLowerCase())
  return version === '' ? family : `${family} ${version}`
}

// turn.step rejects the bare alias ("haiku não está disponível"); it needs the full id.
const MODEL_IDS: Record<Tier, string> = { haiku: 'claude-haiku-5-5', sonnet: 'claude-sonnet-5-5', opus: 'claude-opus-5-5' }

export function modelIdFor(tier: Tier): string {
  return MODEL_IDS[tier]
}

export function modelNotice(text: string | undefined): string | null {
  const name = /Set model to `([^`]+)`/.exec(text ?? '')?.[1]
  return name === undefined ? null : `Modelo da sessão: ${name}`
}

export function effortNotice(text: string | undefined): string | null {
  const level = /Set effort level to (\w+)/.exec(text ?? '')?.[1]
  return level === undefined ? null : `Esforço da sessão: ${level in EFFORT_PT ? EFFORT_PT[level as Effort] : level}`
}

const EFFORT_LABEL: Record<string, string> = { ...EFFORT_PT, xhigh: 'extra alto', max: 'máximo' }

export function effortLabel(raw: unknown): string {
  if (typeof raw === 'number') return String(raw)
  if (typeof raw !== 'string' || raw === '') return ''
  return EFFORT_LABEL[raw.toLowerCase()] ?? raw
}

export function effortFromOutput(text: string | undefined): string | null {
  return /Set effort level to (\w+)/.exec(text ?? '')?.[1]?.toLowerCase() ?? null
}

export function effortWord(effort: Effort): string {
  return EFFORT_PT[effort]
}

const LIMIT = 1500

export function buildPrompt(text: string, lastReply: string): string {
  const context = lastReply.trim() === '' ? '' : `Última resposta do assistente (contexto, cortada): """${lastReply.trim().slice(0, 300)}"""\n`
  return [
    'Escolha o modelo mais barato que dá conta da mensagem do usuário.',
    'haiku: perguntas simples, pesquisa, textos, docs, planilhas, mensagens, uso do browser, edição pontual de código.',
    'sonnet: código com várias etapas (rodar, testar, iterar), features, bugs.',
    'opus: arquitetura, debug difícil, refactors grandes, planejamento, revisão crítica.',
    'esforço: low (trivial), medium (padrão), high (várias etapas ou armadilhas).',
    'Responda numa linha só, neste formato exato: modelo | esforço | motivo em até 8 palavras, em português.',
    'Exemplo: haiku | low | pergunta simples de clima',
    context + `Mensagem do usuário: """${text.trim().slice(0, LIMIT)}"""`,
  ].join('\n')
}

export function parseVerdict(reply: string): Verdict | null {
  const match = /^\s*(haiku|sonnet|opus)\s*\|\s*(low|medium|high)\s*\|\s*(.+?)\s*$/im.exec(reply)
  if (match === null) return null
  return { family: match[1]!.toLowerCase() as Tier, effort: match[2]!.toLowerCase() as Effort, reason: capitalize(match[3]!) }
}

export function gapOf(current: Tier, family: Tier): number {
  return Math.abs(TIERS.indexOf(current) - TIERS.indexOf(family))
}

export type Price = { input: number; output: number; read: number }

// $/MTok from the claude-api reference (cached 2026-10-06); Haiku's cache read is not listed, assumed 0.1x input.
const PRICES: Record<Tier, Price> = {
  haiku: { input: 0.1, output: 0.5, read: 0.01 },
  sonnet: { input: 2, output: 10, read: 0.2 },
  opus: { input: 4, output: 20, read: 0.2 },
}
const HAIKU_LONG: Price = { input: 0.5, output: 2.5, read: 0.05 }
const HAIKU_LONG_FROM = 100_000
// Claude Code writes with the 1-hour TTL, billed at 2x input.
const WRITE = 2
export const CACHE_TTL_MS = 60 * 60 * 1000
const REPLY_TOKENS = 2000
const PAYBACK_TURNS = 3

export function priceFor(tier: Tier, tokens: number): Price {
  return tier === 'haiku' && tokens > HAIKU_LONG_FROM ? HAIKU_LONG : PRICES[tier]
}

export function turnCost(tier: Tier, tokens: number, isWarm: boolean): number {
  const price = priceFor(tier, tokens)
  return (tokens * (isWarm ? price.read : price.input * WRITE) + REPLY_TOKENS * price.output) / 1_000_000
}

export type Economics = { isDown: boolean; isWorth: boolean; ratio: number; saving: number; payback: number }

export function economicsOf(current: Tier, target: Tier, tokens: number, isWarm: boolean): Economics {
  const stay = turnCost(current, tokens, isWarm)
  const change = turnCost(target, tokens, false)
  const saving = turnCost(current, tokens, true) - turnCost(target, tokens, true)
  const extra = change - stay
  const payback = extra <= 0 ? 0 : saving > 0 ? Math.ceil(extra / saving) : Infinity
  return {
    isDown: TIERS.indexOf(target) < TIERS.indexOf(current),
    isWorth: payback <= PAYBACK_TURNS,
    ratio: stay > 0 ? change / stay : 1,
    saving: saving / turnCost(current, tokens, true),
    payback,
  }
}

export function costNote(econ: Economics, tokens: number): string | null {
  const size = `~${Math.round(tokens / 1000)}K tokens`
  if (econ.isDown) {
    const pct = Math.round(econ.saving * 100)
    return econ.payback === 0
      ? `Contexto de ${size}: já fica ~${pct}% mais barato nesta mensagem.`
      : `Contexto de ${size}: compensa em ${econ.payback} mensagens, depois ~${pct}% mais barato.`
  }
  return econ.ratio >= 3 ? `Contexto de ${size}: esta troca custa ~${Math.round(econ.ratio)}× mais nesta mensagem.` : null
}

const ADVISOR_RANK: Record<string, number> = { haiku: 0, sonnet: 1, opus: 2, fable: 3 }

export function advisorRank(raw: unknown): number | null {
  if (typeof raw !== 'string') return null
  const family = /(haiku|sonnet|opus|fable)/i.exec(raw)?.[1]?.toLowerCase()
  return family === undefined ? null : ADVISOR_RANK[family]!
}

export function advisorCovers(advisor: unknown, current: Tier, target: Tier): boolean {
  const rank = advisorRank(advisor)
  if (rank === null) return false
  const to = TIERS.indexOf(target)
  return to > TIERS.indexOf(current) && rank >= to && rank >= TIERS.indexOf(current)
}

export function asDecision(raw: unknown): Decision {
  if (typeof raw === 'string') return { verdict: raw }
  if (typeof raw === 'object' && raw !== null && typeof (raw as Decision).verdict === 'string') return raw as Decision
  return { verdict: 'Nenhuma mensagem avaliada ainda' }
}

export function decisionText(d: Decision): string {
  return [d.verdict, d.route === undefined ? '' : `${d.route}${d.reason === undefined ? '' : ` (${d.reason})`}`, d.detail ?? '']
    .filter(part => part !== '')
    .join(' · ')
}

export function switchedText(p: Pending): string {
  return `Modelo alterado para ${capitalize(p.family)} com esforço ${effortWord(p.effort)}. O seletor do app pode continuar mostrando o anterior.`
}

export function failedText(p: Pending): string {
  return `Não foi possível alterar para ${capitalize(p.family)}. Troque pelo seletor do app.`
}

type Palette = { border: string; fill: string; accent: string; text: string; muted: string }

const CAUTION: Palette = { border: '#d97706', fill: '#3b1d06', accent: '#fbbf24', text: '#fffbeb', muted: '#fcd34d' }
const BIG: Palette = { border: '#dc2626', fill: '#3b0a0a', accent: '#f87171', text: '#fef2f2', muted: '#fca5a5' }

export function paletteFor(gap: number): Palette {
  return gap >= 2 ? BIG : CAUTION
}

export function statusFor(gap: number): string {
  return gap >= 2 ? '❚❚ Aguardando você' : '⇄ Troca sugerida'
}

export function headerFor(p: Pending): string {
  return `${p.gap >= 2 ? '❚❚' : '⇄'} Triagem`
}

export function labelsFor(p: Pending): [string, string, string] {
  return [`Trocar para ${capitalize(p.family)} e enviar`, 'Enviar mesmo assim', 'Cancelar e editar']
}

export function choiceOf(answer: string, p: Pending): Choice | null {
  const [change, send, cancel] = labelsFor(p)
  return answer === change ? 'switch' : answer === send ? 'send' : answer === cancel ? 'cancel' : null
}

export function questionFor(p: Pending) {
  const [change, send, cancel] = labelsFor(p)
  const family = capitalize(p.family)
  const preview = [
    `Atual:         ${p.current}`,
    `Recomendado:   ${family}`,
    `Esforço:       ${effortWord(p.effort)}`,
    `Motivo:        ${p.reason}`,
  ].join('\n')
  return {
    header: headerFor(p),
    question: 'Como seguir com esta mensagem?',
    multiSelect: false,
    options: [
      { label: change, description: `Passa para ${family} com esforço ${effortWord(p.effort)}.`, preview },
      { label: send, description: `Segue com ${p.current}, sem trocar.` },
      {
        label: cancel,
        description: p.hasImages
          ? 'O texto volta para a caixa; as imagens ficam na conversa acima, é só copiar.'
          : 'A mensagem volta para a caixa de texto.',
      },
    ],
  }
}

async function refreshModel($: EngineInterface): Promise<void> {
  try {
    const name = prettyModel(String(await $.session.model()))
    await update($, shownModel, () => name)
  } catch {
    return
  }
}

async function readAdvisor($: { settings: { read: () => Promise<unknown> } }): Promise<unknown> {
  try {
    return ((await $.settings.read()) as Record<string, unknown>).advisorModel
  } catch {
    return undefined
  }
}

export const register: Register = on => {
  // 0 = unknown (fresh load): treated as a warm cache, which only makes downgrades rarer.
  let lastTurnAt = 0
  // Set synchronously right before $.ui.ask so the AskUserQuestion render never reads a stale atom.
  let askedNow: Pending | null = null

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'triage-gate',
      description: 'Pre-message model triage: on | off | modal | band | why | demo [1|2].',
      argumentHint: 'on | off | modal | band | why | demo [1|2]',
    })
    const result = await next(e)
    await refreshModel($)
    const saved = await $.store.get('isBandOpen')
    if (typeof saved === 'boolean') await update($, isBandOpen, () => saved)
    return result
  })

  on('command.run', { command: 'triage-gate' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'on' || arg === 'off') await update($, isOn, () => arg === 'on')
    if (arg === 'off') await update($, pending, () => null)
    if (arg === 'modal' || arg === 'band') await update($, isModal, () => arg === 'modal')
    if (arg === 'why') return { text: `Última decisão da triagem: ${decisionText(asDecision(await read($, decision)))}` }
    if (arg.startsWith('demo')) {
      const big = arg.endsWith('2')
      const sample: Pending = {
        text: 'demo',
        current: big ? 'Opus 5.5' : 'Sonnet 5.5',
        family: 'haiku',
        effort: 'low',
        reason: 'Pergunta simples de clima',
        gap: big ? 2 : 1,
      }
      await update($, asking, () => sample)
      let answer = ''
      try {
        answer = await $.ui.ask(questionFor(sample).question, { options: labelsFor(sample), header: headerFor(sample) })
      } catch (error) {
        answer = `(modal recusado: ${String(error)})`
      }
      await update($, asking, () => null)
      return { text: `Demo do modal. Resposta: ${answer} → ${choiceOf(answer, sample) ?? 'nenhuma das opções'}` }
    }
    const state = (await read($, isOn)) ? 'ligada' : 'desligada'
    const style = (await read($, isModal)) ? 'modal em todas as mensagens' : 'faixa (modal só com imagem)'
    const advisor = await readAdvisor($)
    const advisorText = advisorRank(advisor) === null ? 'sem advisor' : `advisor ${String(advisor)} (não sugere subir até ele)`
    return { text: `Triagem antes da mensagem: ${state}, ${style}, ${advisorText}. Use /triage-gate on | off | modal | band | demo.` }
  })

  on('command.run', { command: 'model' }, async ($, e, next) => {
    const result = await next(e)
    await refreshModel($)
    const notice = e.origin.kind === 'plugin' && e.origin.name.includes('triage-gate') ? modelNotice(result.text) : null
    return notice === null ? result : { ...result, text: notice }
  })

  on('command.run', { command: 'effort' }, async ($, e, next) => {
    const result = await next(e)
    const level = effortFromOutput(result.text)
    if (level !== null) await update($, shownEffort, () => level)
    const notice = e.origin.kind === 'plugin' && e.origin.name.includes('triage-gate') ? effortNotice(result.text) : null
    return notice === null ? result : { ...result, text: notice }
  })

  on('prompt.submit', async ($, e, next) => {
    if (e.origin.kind !== 'composer' || e.turnId !== undefined) return next(e)
    const decide = (d: Decision) => update($, decision, () => d)
    await update($, pending, () => null)
    if (!(await read($, isOn))) {
      await decide({ verdict: 'Triagem desligada', detail: 'Use /triage-gate on para ligar.' })
      return next(e)
    }
    if (isSkippable(e.text)) {
      await decide({ verdict: 'Passou sem triagem', detail: 'Mensagem curta, comando ou continuação.' })
      return next(e)
    }

    let current: Tier | null = null
    let verdict: Verdict | null = null
    let currentName = ''
    try {
      currentName = String(await $.session.model())
      current = familyOf(currentName)
      const rows = await $.session.messages()
      const lastReply = rows.filter(row => row.role === 'assistant').at(-1)?.text ?? ''
      const answer = await $.model.complete({
        model: 'haiku',
        prompt: buildPrompt(e.text, lastReply),
        maxTokens: 60,
        effort: 'low',
        timeoutMs: 8000,
      })
      verdict = answer.isAnswered ? parseVerdict(answer.text) : null
    } catch {
      verdict = null
    }
    if (currentName !== '') await update($, shownModel, () => prettyModel(currentName))
    if (current === null || verdict === null) {
      await decide({ verdict: 'Passou sem triagem', detail: 'O classificador não respondeu a tempo.' })
      return next(e)
    }

    const gap = gapOf(current, verdict.family)
    const route = `${prettyModel(currentName)} → ${capitalize(verdict.family)}`
    const reason = verdict.reason
    if (gap === 0) {
      await decide({ verdict: 'Sem troca: o modelo atual é o recomendado', route: prettyModel(currentName), reason })
      return next(e)
    }

    let tokens = 0
    try {
      tokens = (await $.session.usage()).context.tokens ?? 0
    } catch {
      tokens = 0
    }
    const isWarm = lastTurnAt === 0 || (await $.clock.now()) - lastTurnAt < CACHE_TTL_MS
    const econ = economicsOf(current, verdict.family, tokens, isWarm)
    const size = `Contexto de ~${Math.round(tokens / 1000)}K tokens, cache ${isWarm ? 'ativo' : 'expirado'}`
    if (econ.isDown && !econ.isWorth) {
      const when = econ.payback === Infinity ? 'nunca se pagaria' : `só se pagaria em ${econ.payback} mensagens`
      await decide({ verdict: 'Sem troca: descer não compensa', route, reason, detail: `${size}; a troca ${when}.` })
      return next(e)
    }
    if (advisorCovers(await readAdvisor($), current, verdict.family)) {
      await decide({ verdict: 'Sem troca: o advisor cobre a subida', route, reason, detail: 'O Opus é consultado nos momentos difíceis, sem perder o cache.' })
      return next(e)
    }
    await decide({ verdict: 'Troca sugerida no modal', route, reason, detail: `${size}.` })

    const p: Pending = {
      text: e.text,
      current: prettyModel(currentName),
      family: verdict.family,
      effort: verdict.effort,
      reason: verdict.reason,
      gap,
      hasImages: e.attachments !== undefined,
      note: tokens > 0 ? (costNote(econ, tokens) ?? undefined) : undefined,
    }

    if (e.attachments !== undefined || (await read($, isModal))) {
      const askedAt = await $.clock.now()
      askedNow = p
      await update($, asking, () => p)
      let answer = ''
      let isRefused = false
      try {
        answer = await $.ui.ask(questionFor(p).question, { options: labelsFor(p), header: headerFor(p) })
      } catch {
        isRefused = (await $.clock.now()) - askedAt < 700
      }
      askedNow = null
      await update($, asking, () => null)
      if (isRefused) {
        $.ui.toast('O modal da triagem não abriu; a mensagem foi enviada sem triagem.')
        return next(e)
      }
      const choice = choiceOf(answer, p)
      if (choice === 'switch') {
        await update($, override, () => ({ model: p.family, effort: p.effort }))
        $.ui.toast(switchedText(p))
        return next(e)
      }
      if (choice === 'send') return next(e)
      await $.prompt.fill({ text: e.text })
      if (e.attachments !== undefined) $.ui.toast('As imagens não voltam para a caixa, mas ficam na conversa acima: copie e cole.')
      return { drop: 'Envio cancelado: a mensagem voltou para a caixa de texto.' }
    }

    await update($, pending, () => p)
    return { drop: 'Mensagem retida pela triagem: veja a faixa acima do campo de digitação.' }
  })

  on('turn.step', async function* ($, e, next) {
    if (e.agentId !== undefined) return yield* next(e)
    const chosen = await read($, override)
    const sent = chosen === null ? e.effort : chosen.effort
    const level = sent === undefined ? '' : String(sent)
    if (level !== '' && level !== (await read($, shownEffort))) await update($, shownEffort, () => level)
    if (chosen === null) return yield* next(e)
    return yield* next({ ...e, model: modelIdFor(chosen.model), effort: chosen.effort })
  })

  on('turn.complete', async ($, e, next) => {
    const chosen = await read($, override)
    const result = await next(e)
    lastTurnAt = await $.clock.now()
    if (chosen === null) return result
    await update($, override, () => null)
    try {
      await $.command.run({ command: 'model', args: chosen.model })
      await $.command.run({ command: 'effort', args: chosen.effort })
    } catch (error) {
      $.ui.log(`[triage-gate] não consegui fixar o modelo da sessão: ${String(error).slice(0, 240)}`)
    }
    await refreshModel($)
    return result
  })

  on('ui.render', { component: 'AskUserQuestion' }, async ($, e, next) => {
    const p = askedNow ?? (await read($, asking))
    if (p === null) return next(e)
    const native = await next({ ...e, props: { ...e.props, questions: [questionFor(p)] } })

    const { Box, Text } = $.ui.resolve(e)
    const pal = paletteFor(p.gap)
    const banner = (
      <Box flexDirection="column" borderStyle="round" borderDimColor paddingX={2} paddingY={1} marginBottom={1}>
        <Box flexDirection="row" justifyContent="space-between">
          <Text bold>Triagem de modelo</Text>
          <Text bold color={pal.accent}>
            {statusFor(p.gap)}
          </Text>
        </Box>
        <Box flexDirection="column" marginTop={1}>
          <Text bold>
            {p.current} → {capitalize(p.family)}
          </Text>
          <Text dimColor>
            Esforço {effortWord(p.effort)} · {p.reason}
          </Text>
          {p.note === undefined ? null : <Text dimColor>{p.note}</Text>}
        </Box>
      </Box>
    )
    return (
      <Box flexDirection="column">
        {banner}
        {native}
      </Box>
    )
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const p = await read($, pending)
    if (p === null) {
      const { Box, Text, Button } = $.ui.resolve(e)
      const model = await read($, shownModel)
      const effort = effortLabel(await read($, shownEffort))
      const why = asDecision(await read($, decision))
      const isOpen = await read($, isBandOpen)
      const advisor = await readAdvisor($)
      const advisorName = advisorRank(advisor) === null ? null : prettyModel(String(advisor))
      const head = (
        <Box flexDirection="row" flexGrow={1} justifyContent="space-between" alignItems="center" columnGap={2}>
          <Box flexDirection="row" columnGap={1}>
            <Text dimColor>Modelo em uso</Text>
            <Text bold>{model === '' ? '…' : model}</Text>
            {effort === '' ? null : <Text dimColor>· esforço {effort}</Text>}
            {advisorName === null ? null : <Text dimColor>· advisor {advisorName}</Text>}
          </Box>
          <Button
            key="toggle"
            variant="secondary"
            onPress={async () => {
              await update($, isBandOpen, () => !isOpen)
              await $.store.set('isBandOpen', !isOpen)
            }}
          >
            {isOpen ? 'Minimizar' : 'Triagem'}
          </Button>
        </Box>
      )
      if (!isOpen) {
        return (
          <Box flexDirection="column" paddingX={1}>
            {head}
          </Box>
        )
      }
      return (
        <Box flexDirection="column" borderStyle="round" borderDimColor paddingX={1}>
          {head}
          <Box marginTop={1}>
            <Text dimColor wrap="wrap">
              Triagem: {decisionText(why)}
            </Text>
          </Box>
        </Box>
      )
    }

    const { Box, Text, Button } = $.ui.resolve(e)
    const pal = paletteFor(p.gap)
    const fill = { color: pal.text, backgroundColor: pal.fill }
    const label = { bold: true, color: pal.muted, backgroundColor: pal.fill }
    const strong = { bold: true, color: pal.text, backgroundColor: pal.fill }

    const send = async (): Promise<void> => {
      await update($, pending, () => null)
      void $.prompt.submit({ text: p.text, asUser: true })
    }

    return (
      <Box flexDirection="column" borderStyle="round" borderColor={pal.border} backgroundColor={pal.fill} paddingX={1}>
        <Box flexDirection="row" columnGap={1}>
          <Text color={pal.muted} backgroundColor={pal.fill}>
            ◈ Triagem
          </Text>
          <Text bold color={pal.accent} backgroundColor={pal.fill}>
            {statusFor(p.gap)}
          </Text>
        </Box>
        <Box flexDirection="row" columnGap={1}>
          <Text {...label}>Atual:</Text>
          <Text {...strong}>{p.current}</Text>
          <Text {...label}>→ Recomendado:</Text>
          <Text {...strong}>{capitalize(p.family)}</Text>
          <Text {...fill}>· Esforço {effortWord(p.effort)}</Text>
        </Box>
        <Box flexDirection="row" columnGap={1}>
          <Text {...label}>Motivo:</Text>
          <Text {...fill}>{p.reason}</Text>
        </Box>
        <Box flexDirection="row" columnGap={1} marginTop={1}>
          <Button
            key="switch"
            variant="primary"
            onPress={async () => {
              const model = await $.command.run({ command: 'model', args: p.family })
              if (model.exitCode) return $.ui.toast(failedText(p))
              await $.command.run({ command: 'effort', args: p.effort })
              $.ui.toast(switchedText(p))
              await send()
            }}
          >
            {`Trocar para ${capitalize(p.family)} e enviar`}
          </Button>
          <Button key="send" variant="secondary" onPress={() => void send()}>
            Enviar mesmo assim
          </Button>
          <Button
            key="edit"
            variant="secondary"
            onPress={async () => {
              await update($, pending, () => null)
              await $.prompt.fill({ text: p.text })
            }}
          >
            Editar
          </Button>
        </Box>
      </Box>
    )
  })
}

